import{_ as t,o as a,c as o,a2 as r}from"./chunks/framework.BWuWLRhz.js";const p=JSON.parse('{"title":"User Guide","description":"","frontmatter":{},"headers":[],"relativePath":"user-guide/index.md","filePath":"user-guide/index.md","lastUpdated":1788366161000}'),i={name:"user-guide/index.md"};function n(s,e,l,d,c,g){return a(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="user-guide" tabindex="-1">User Guide <a class="header-anchor" href="#user-guide" aria-label="Permalink to &quot;User Guide&quot;">​</a></h1><p>Welcome to the official Lertaro User Guide! Lertaro is an ultra-fast file search launcher and productivity powerhouse built specifically for Windows. By maintaining an in-memory index tree in the background (via NTFS/ReFS USN change journals and realtime filesystem event listeners), it delivers sub-millisecond query responses across millions of items.</p><p>This guide systematically covers all core features and advanced capabilities needed for daily workflows:</p><ul><li><strong><a href="./getting-started.html">Getting Started</a></strong> —— Installation, portable usage, architecture overview, three window modes (Quick / Full / Inline), and essential operations.</li><li><strong><a href="./search-syntax.html">Search Syntax</a></strong> —— Fuzzy matching, operators (<code>!</code> exclude, <code>&#39;</code> exact, <code>^</code> prefix, <code>$</code> suffix, <code>|</code> OR), drive prefixes, path mode, and multilingual pinyin aliases.</li><li><strong><a href="./hotkeys.html">Hotkeys &amp; Gestures</a></strong> —— Global hotkeys cheat sheet, search box logo drag/reset gestures, mouse Quick Navigation cascading menus, and hardcoded keys.</li><li><strong><a href="./actions-and-preview.html">Actions &amp; Preview</a></strong> —— Context action menu (<code>Ctrl+O</code>), Full Window results list, built-in QuickLook media/document previews, and interactive plugin cards.</li><li><strong><a href="./space-analyzer.html">Space Analyzer</a></strong> —— Zero-I/O Treemap visualization and sorted size breakdown for effortless storage cleanup.</li><li><strong><a href="./instant-answers.html">Instant Answers &amp; Keyword Features</a></strong> —— Always-active calculator, environment variables, commands, and keyword plugins like Process Manager (<code>ps</code>), Window Switcher (<code>win</code>), Browser Bookmarks (<code>bb</code>), Browser History (<code>bh</code>), and Settings Search (<code>set</code>).</li><li><strong><a href="./cli.html">CLI Search (lff)</a></strong> —— Terminal companion tool for interactive fuzzy finding, sharing the memory index with pipeline and shell integration.</li><li><strong><a href="./uri-protocol.html">URI Protocol (lertaro://)</a></strong> —— Deep-linking from browsers, shortcuts, and scripts to searches, settings pages, and LocalSend transfers.</li><li><strong><a href="./file-manager-support.html">Supported File Managers</a></strong> —— Integration with Windows dialogs, Directory Opus, Total Commander, XYplorer, Files, and One Commander.</li><li><strong><a href="./settings/">Settings Reference</a></strong> —— Comprehensive walkthrough of Service Status, Indexing, General, Appearance, Hotkeys, and Plugin options.</li><li><strong><a href="./troubleshooting.html">Troubleshooting</a></strong> —— Step-by-step diagnostic guide for hotkeys, indexing, IMEs, and live log inspection.</li><li><strong><a href="./donate.html">Donate &amp; Support</a></strong> —— Support the ongoing development and open-source maintenance of Lertaro.</li></ul><div class="tip custom-block github-alert"><p class="custom-block-title">TIP</p><p>If you are new to Lertaro, we recommend starting with <a href="./getting-started.html"><strong>Getting Started</strong></a>.</p></div>',5)])])}const h=t(i,[["render",n]]);export{p as __pageData,h as default};
